// summary.js - the research summary page.
//
// Every number on this page is fetched from /api/analysis/summary at
// render time rather than written into the template, so the page cannot
// drift from the record the way a hardcoded figure would. The figures
// themselves are static images generated by docs/analysis/.

const MODEL_LABEL = {
  logreg: "Logistic regression",
  svm: "SVM",
  random_forest: "Random forest",
  gradient_boosting: "Gradient boosting",
};

const FACTOR_ORDER = ["scaling", "encoding", "selection", "tuning"];

function statTile(label, value, note) {
  const tile = document.createElement("div");
  tile.className = "stat-tile";
  const v = document.createElement("div");
  v.className = "stat-value";
  v.textContent = value;
  const l = document.createElement("div");
  l.className = "stat-label";
  l.textContent = label;
  tile.appendChild(v);
  tile.appendChild(l);
  if (note) tile.title = note;
  return tile;
}

/** Headline counts across the whole programme. */
function renderTotals(data) {
  const target = document.getElementById("totals");
  clearChildren(target);
  const t = data.totals;
  const tiles = [
    ["Runs recorded", t.total_runs.toLocaleString(),
      "One run is one dataset, one model and one setting of the thing "
      + "being tested, scored by cross-validation."],
    ["Datasets", String(t.datasets), "Distinct datasets in the record."],
    ["Models", String(t.models), "Model families compared throughout."],
    ["Compute", t.hours + " hours",
      "Total wall-clock time across every recorded run."],
  ];
  tiles.forEach(([label, value, note]) => {
    target.appendChild(statTile(label, value, note));
  });

  const caption = document.getElementById("totals-caption");
  caption.textContent =
    t.succeeded.toLocaleString() + " runs produced a score, "
    + t.skipped + " were refused with a recorded reason, and "
    + t.failed + " failed. Every failure has a documented cause and fix.";
}

/** The factor-by-model sensitivity map: the page's main result. */
function renderSensitivity(data) {
  const target = document.getElementById("sensitivity-table");
  clearChildren(target);

  const models = Object.keys(MODEL_LABEL);
  const rows = models.map((model) => {
    const row = { Model: MODEL_LABEL[model] };
    FACTOR_ORDER.forEach((factor) => {
      const value = (data.sensitivity[factor] || {})[model];
      const key = factor.charAt(0).toUpperCase() + factor.slice(1);
      row[key] = value === undefined ? null : value.toFixed(2) + "%";
    });
    return row;
  });

  const table = buildTable(rows);
  if (!table) {
    showBanner(target, "The record returned no sensitivity data.", "error");
    return;
  }
  // Emphasise the cells a reader should act on. Colour is not the only
  // channel: the number itself carries the message, and the caption and
  // verdict state it in words.
  table.querySelectorAll("tbody tr").forEach((tr) => {
    Array.from(tr.children).forEach((td, i) => {
      if (i === 0) return;
      const n = parseFloat(td.textContent);
      if (!Number.isNaN(n) && n >= 3.0) td.style.fontWeight = "600";
    });
  });
  target.appendChild(table);

  // Verdict is computed, not asserted: find the largest cell and name it.
  let best = { value: -1, model: null, factor: null };
  FACTOR_ORDER.forEach((factor) => {
    Object.entries(data.sensitivity[factor] || {}).forEach(([model, v]) => {
      if (v > best.value) best = { value: v, model, factor };
    });
  });
  const verdict = document.getElementById("sensitivity-verdict");
  if (best.model) {
    verdict.textContent =
      "The choice that moves the score most is " + best.factor + ", on "
      + MODEL_LABEL[best.model] + ", at " + best.value.toFixed(2)
      + " percent. Encoding moves nothing for any model here, and scaling "
      + "is irrelevant to both tree ensembles.";
  } else {
    verdict.textContent = "No sensitivity data in the record.";
  }
}

/** Compute spent per factor, against the evidence it produced. */
function renderCost(data) {
  const target = document.getElementById("cost-table");
  clearChildren(target);
  const total = data.factors.reduce((sum, f) => sum + f.hours, 0);
  const rows = data.factors.map((f) => ({
    Factor: f.factor.charAt(0).toUpperCase() + f.factor.slice(1),
    Runs: f.runs.toLocaleString(),
    Hours: f.hours.toFixed(1),
    "Share of compute": total > 0
      ? (100 * f.hours / total).toFixed(0) + "%" : "0%",
  }));
  const table = buildTable(rows);
  if (table) target.appendChild(table);
}

/** The discreteness floor: why five results could not be confirmed. */
function renderPower() {
  const target = document.getElementById("power-table");
  clearChildren(target);
  // Computed from the test's own arithmetic rather than transcribed:
  // the smallest two-sided Wilcoxon p on n pairs is 2 / 2^n, and Holm
  // multiplies the smallest of k comparisons by k.
  const rows = [7, 9, 11].flatMap((n) => [3, 4].map((k) => {
    const smallest = (2 / Math.pow(2, n)) * k;
    return {
      Datasets: String(n),
      "Options compared": String(k),
      "Smallest possible result": smallest.toFixed(4),
      Verdict: smallest < 0.05
        ? "can be confirmed"
        : "cannot be confirmed, whatever the effect",
    };
  }));
  const table = buildTable(rows);
  if (!table) return;
  table.querySelectorAll("tbody tr").forEach((tr) => {
    const cells = Array.from(tr.children);
    if (cells[3] && cells[3].textContent.startsWith("cannot")) {
      cells.forEach((td) => { td.style.fontWeight = "600"; });
    }
  });
  target.appendChild(table);
}

async function render() {
  const totals = document.getElementById("totals");
  let data;
  try {
    data = await apiCall("/api/analysis/summary");
  } catch (err) {
    clearChildren(totals);
    showBanner(totals, "Could not read the run record: " + err.message, "error");
    return;
  }
  renderTotals(data);
  renderSensitivity(data);
  renderCost(data);
  renderPower();
}

document.addEventListener("DOMContentLoaded", render);
